using System;
using System.Collections.Generic;
using System.IO;

using Colossal;

using Newtonsoft.Json;

namespace ShelveIt
{
	// Reads the embedded Locale\<locale>.json. Keys starting with "Setting." are mapped to the
	// option ids generated by ModSetting, every other key is registered as written.
	public class LocaleSource : IDictionarySource
	{
		public static readonly string[] kLocales = { "en-US", "it-IT" };

		private readonly string m_Locale;
		private readonly Setting m_Setting;

		public LocaleSource(string locale, Setting setting)
		{
			m_Locale = locale;
			m_Setting = setting;
		}

		public IEnumerable<KeyValuePair<string, string>> ReadEntries(IList<IDictionaryEntryError> errors, Dictionary<string, int> indexCounts)
		{
			var result = new Dictionary<string, string>();

			try
			{
				using (var stream = typeof(LocaleSource).Assembly.GetManifestResourceStream($"ShelveIt.Locale.{m_Locale}.json"))
				using (var reader = new StreamReader(stream))
				{
					foreach (var entry in JsonConvert.DeserializeObject<Dictionary<string, string>>(reader.ReadToEnd()))
					{
						result[MapKey(entry.Key)] = entry.Value;
					}
				}
			}
			catch (Exception ex)
			{
				Mod.Log.Error($"Could not load locale {m_Locale}: {ex.Message}");
			}

			return result;
		}

		private string MapKey(string key)
		{
			if (!key.StartsWith("Setting."))
			{
				return key;
			}

			var parts = key.Split('.');

			if (parts.Length == 2 && parts[1] == "Title")
			{
				return m_Setting.GetSettingsLocaleID();
			}

			if (parts.Length != 3)
			{
				return key;
			}

			switch (parts[1])
			{
				case "Tab": return m_Setting.GetOptionTabLocaleID(parts[2]);
				case "Group": return m_Setting.GetOptionGroupLocaleID(parts[2]);
				case "Label": return m_Setting.GetOptionLabelLocaleID(parts[2]);
				case "Desc": return m_Setting.GetOptionDescLocaleID(parts[2]);
				default: return key;
			}
		}

		public void Unload()
		{
		}
	}
}
